"""Offline synthetic admission/transaction tests; no GitHub or real state calls."""
import copy
import importlib.util
import json
import tempfile
import unittest
from datetime import UTC, datetime
from pathlib import Path
from unittest.mock import patch
SCRIPT = Path(__file__).with_name('reconcile-ci-resume-b096.py')
spec = importlib.util.spec_from_file_location('resume_under_test', SCRIPT)
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)

class ResumeTests(unittest.TestCase):

    def setUp(self):
        self.now = datetime(2026, 11, 11, 21, tzinfo=UTC)
        self.old = {'status': 'head_ci_failed_or_cutoff', 'head_sha': m.OLD_HEAD, 'pr_number': m.PR, 'pr_url': 'https://github.com/' + PARAMETERS['repository'] + '/pull/' + str(PARAMETERS['pr_number']), 'patch_sha256': 'a' * 64, 'review_receipt_sha256': 'b' * 64, 'started_at_utc': '2026-11-11T20:14:52Z'}
        self.state = {'paused': False, 'tasks': {f'B{i:03}': {'status': 'merged_green_provisional'} for i in range(1, 59)}, 'post_merge_checks': {'B001': {'status': 'passed', 'merged_tree_verified': True, 'requires_coordinator_reconciliation': False}}}
        self.state['tasks'][m.TASK] = copy.deepcopy(self.old)
        self.events = [{'kind': 'head_ci_wait_finished', 'task_id': m.TASK, 'status': 'pending', 'at_utc': '2026-11-11T20:31:05Z'}, {'kind': 'integration_queue_stopped', 'paused': False, 'cutoff_reached': False, 'at_utc': '2026-11-11T20:31:06Z', 'task_status_counts': {'head_ci_failed_or_cutoff': 1, 'merged_green_provisional': 58}}]
        self.integration = {'status': 'published', 'head_sha': 'd' * 40, 'pr_number': m.PR, 'branch': 'owned-recovery-B096', 'tested_base_sha': 'c' * 40, 'tested_tree': 'e' * 40, 'patch_sha256': 'a' * 64, 'batch_id': 'recovery-separate', 'application_method': 'direct', 'checks_started_at': '2026-11-11T20:15:00Z', 'checks_finished_at': '2026-11-11T20:15:55Z', 'reviewed_at': '2026-11-11T20:16:00Z', 'published_at': '2026-11-11T20:16:08Z'}
        self.original_integration = {**self.integration, 'head_sha': m.OLD_HEAD}
        self.state_raw = json.dumps(self.state).encode()
        self.attestation = {'kind': 'coordinator_same_tree_ci_retry', 'actor': 'root', 'task_id': m.TASK, 'pr_number': m.PR, 'old_head_sha': m.OLD_HEAD, 'new_head_sha': self.integration['head_sha'], 'new_paid_workers': 0, 'code_delta': False, 'exact_old_head_lease_succeeded': True, 'recorded_at_utc': '2026-11-11T20:40:00Z', 'old_queue_state_sha256': m.sha(self.state_raw), 'reviewed_patch_sha256': 'a' * 64, 'review_receipt_sha256': 'b' * 64, 'tested_base_sha': 'c' * 40, 'tested_tree': 'e' * 40}

    def validate_stop(self):
        return m.validate_stop(self.state, self.events, self.now, datetime(2026, 11, 11, 22, tzinfo=UTC).timestamp())

    def validate_attestation(self):
        m.validate_attestation(self.attestation, self.original_integration, self.integration, self.old, self.state_raw, 'b' * 64, self.now)

    def query(self, endpoint):
        if endpoint == 'pulls/' + str(PARAMETERS['pr_number']):
            return {'state': 'open', 'merged': False, 'draft': False, 'head': {'sha': self.integration['head_sha'], 'ref': self.integration['branch'], 'repo': {'full_name': PARAMETERS['repository']}}, 'base': {'ref': 'main'}}
        if endpoint == 'git/ref/heads/main':
            return {'object': {'sha': self.integration['tested_base_sha']}}
        return {'sha': endpoint.rsplit('/', 1)[-1], 'tree': {'sha': self.integration['tested_tree']}, 'parents': [{'sha': self.integration['tested_base_sha']}]}

    def test_genuine_stopped_pending_snapshot_is_accepted(self):
        self.assertEqual(self.validate_stop(), self.old)

    def test_live_or_incomplete_or_reconciliating_stop_is_rejected(self):
        for mutation in [lambda: self.state.update(paused=True), lambda: self.state['tasks'].pop('B001'), lambda: self.state['tasks'][m.TASK].update(status='waiting_head_ci'), lambda: self.state['post_merge_checks']['B001'].update(requires_coordinator_reconciliation=True)]:
            before = copy.deepcopy(self.state)
            mutation()
            with self.assertRaises(ValueError):
                self.validate_stop()
            self.state = before

    def test_red_old_result_and_future_stop_and_deadline_are_rejected(self):
        self.events[0]['status'] = 'failed'
        with self.assertRaises(ValueError):
            self.validate_stop()
        self.events[0]['status'] = 'pending'
        self.events[-1]['at_utc'] = '2026-11-11T21:01:00Z'
        with self.assertRaises(ValueError):
            self.validate_stop()
        self.events[-1]['at_utc'] = '2026-11-11T20:31:06Z'
        with self.assertRaises(ValueError):
            m.validate_stop(self.state, self.events, self.now, self.now.timestamp() + 29)

    def test_same_tree_attestation_accepts_exact_preserved_metadata(self):
        self.validate_attestation()

    def test_same_tree_claim_cannot_change_review_parent_tree_or_paid_scope(self):
        for key, value in [('tested_tree', 'f' * 40), ('tested_base_sha', 'f' * 40), ('reviewed_patch_sha256', 'f' * 64), ('review_receipt_sha256', 'f' * 64), ('old_queue_state_sha256', 'f' * 64), ('new_paid_workers', False), ('exact_old_head_lease_succeeded', False), ('code_delta', True)]:
            previous = self.attestation[key]
            self.attestation[key] = value
            with self.assertRaises(ValueError):
                self.validate_attestation()
            self.attestation[key] = previous

    def test_new_head_never_resets_original_review_or_publication_clock(self):
        for key in ['reviewed_at', 'published_at', 'checks_finished_at']:
            previous = self.integration[key]
            self.integration[key] = '2026-11-11T20:40:00Z'
            with self.assertRaises(ValueError):
                self.validate_attestation()
            self.integration[key] = previous

    def test_real_remote_contract_accepts_green_same_parent_and_tree(self):
        m.validate_remote(self.query, lambda _: ('passed', {}), self.integration)

    def test_pending_red_or_incomplete_checks_cannot_merge(self):
        for status in ['pending', 'failed', 'unknown']:
            with self.assertRaises(ValueError):
                m.validate_remote(self.query, lambda _, status=status: (status, {}), self.integration)

    def test_remote_stale_head_changed_main_or_extra_parent_is_rejected(self):
        for endpoint in ['pulls/' + str(PARAMETERS['pr_number']), 'git/ref/heads/main', f'git/commits/{m.OLD_HEAD}']:

            def bad_query(path, endpoint=endpoint):
                result = self.query(path)
                if path == endpoint:
                    if path.startswith('pulls'):
                        result['head']['sha'] = m.OLD_HEAD
                    elif path.startswith('git/ref'):
                        result['object']['sha'] = 'f' * 40
                    else:
                        result['parents'].append({'sha': 'f' * 40})
                return result
            with self.assertRaises(ValueError):
                m.validate_remote(bad_query, lambda _: ('passed', {}), self.integration)

    def transaction(self, root, code=0, bad_tree=False):
        attempt, archive = (root / 'attempt', root / 'archive')
        attempt.mkdir()
        archive.mkdir()
        marker = root / 'stop'
        marker.write_bytes(b'hold exact bytes')
        state_path = root / 'state.json'
        state_path.write_bytes(self.state_raw)
        logged = []
        merged = {**self.integration, 'status': 'merged', 'merge_commit_sha': 'f' * 40, 'merged_at': '2026-11-11T21:00:00Z'}

        def operation(*_):
            self.assertFalse(marker.exists())
            (attempt / 'integration.json').write_text(json.dumps(merged))
            return (code, b'', root / 'receipt.json')

        def query(endpoint):
            if endpoint.startswith('pulls'):
                return {'merged': True, 'merge_commit_sha': 'f' * 40, 'head': {'sha': self.integration['head_sha']}}
            return {'sha': 'f' * 40, 'tree': {'sha': 'a' * 40 if bad_tree else self.integration['tested_tree']}}
        q = {'operation': operation, 'PYTHON': 'synthetic-python', 'PHASE_HELPER': root / 'synthetic-helper.py', 'query': query, 'STATE': state_path, 'state': copy.deepcopy(self.state), 'save': lambda: state_path.write_text(json.dumps(q['state'])), 'event': lambda kind, **fields: logged.append({'kind': kind, **fields}), 'utc': lambda: '2026-11-11T21:00:02Z'}
        return (q, attempt, archive, marker, state_path, logged)

    def test_nonzero_merge_restores_stop_and_preserves_state_with_no_retry(self):
        with tempfile.TemporaryDirectory() as temp:
            q, attempt, archive, marker, state_path, _ = self.transaction(Path(temp), code=1)
            for _ in range(2):
                with self.assertRaises(ValueError):
                    m.finish_merge(q, attempt, archive, marker, b'hold exact bytes', self.old, self.integration, {'total_head_wait_envelope_seconds': 2000, 'old_state_sha256': m.sha(self.state_raw)})
            self.assertEqual(state_path.read_bytes(), self.state_raw)
            self.assertEqual(marker.read_bytes(), b'hold exact bytes')

    def test_actual_merge_with_wrong_tree_never_updates_queue_state(self):
        with tempfile.TemporaryDirectory() as temp:
            q, attempt, archive, marker, state_path, _ = self.transaction(Path(temp), bad_tree=True)
            with self.assertRaises(ValueError):
                m.finish_merge(q, attempt, archive, marker, b'hold exact bytes', self.old, self.integration, {'total_head_wait_envelope_seconds': 2000, 'old_state_sha256': m.sha(self.state_raw)})
            self.assertEqual(state_path.read_bytes(), self.state_raw)
            self.assertTrue(marker.exists())

    def test_verified_merge_is_only_pending_combined_and_history_is_preserved(self):
        with tempfile.TemporaryDirectory() as temp:
            q, attempt, archive, marker, state_path, logged = self.transaction(Path(temp))
            m.finish_merge(q, attempt, archive, marker, b'hold exact bytes', self.old, self.integration, {'total_head_wait_envelope_seconds': 2000, 'old_state_sha256': m.sha(self.state_raw)})
            actual = json.loads(state_path.read_text())
            self.assertEqual(actual['tasks'][m.TASK]['status'], 'merged_pending_combined_ci')
            self.assertEqual(actual['post_merge_checks'][m.TASK]['status'], 'pending')
            self.assertEqual(actual['task_history'][m.TASK], [self.old])
            self.assertEqual(actual['tasks'][m.TASK]['head_sha'], self.integration['head_sha'])
            self.assertEqual(marker.read_bytes(), b'hold exact bytes')
            self.assertEqual(logged[0]['wall_seconds'], 2000)
            self.assertTrue(logged[0]['durations_are_not_additive'])

    def test_concurrent_state_change_is_preserved_after_known_merge(self):
        with tempfile.TemporaryDirectory() as temp:
            q, attempt, archive, marker, state_path, _ = self.transaction(Path(temp))
            original_operation = q['operation']

            def operation(*args):
                result = original_operation(*args)
                state_path.write_bytes(b'{"another_operator":"must_not_be_overwritten"}')
                return result
            q['operation'] = operation
            with self.assertRaises(ValueError):
                m.finish_merge(q, attempt, archive, marker, b'hold exact bytes', self.old, self.integration, {'total_head_wait_envelope_seconds': 2000, 'old_state_sha256': m.sha(self.state_raw)})
            self.assertEqual(json.loads(state_path.read_text()), {'another_operator': 'must_not_be_overwritten'})
            self.assertTrue(marker.exists())

    def test_prefix_import_never_executes_queue_assert_or_body(self):
        with tempfile.TemporaryDirectory() as temp:
            path = Path(temp) / 'queue.py'
            raw = b'import json\nstate={}\nassert "owner-release.json"\nraise RuntimeError("queue body must not run")\n'
            path.write_bytes(raw)
            with patch.object(m, 'QUEUE_SHA', m.sha(raw)):
                result = m.load_queue_prefix(path)
            self.assertEqual(result['state'], {})
            with self.assertRaises(ValueError):
                m.load_queue_prefix(path)
if __name__ == '__main__':
    unittest.main()
